import math
N, avgdl, k1, b = 1000, 20.0, 1.2, 0.75
df = {"cheap": 200, "flights": 50}

def idf(t):
    n = df[t]
    return math.log(1 + (N - n + 0.5) / (n + 0.5))

def bm25(query, tf, dl):
    K = k1 * ((1 - b) + b * dl / avgdl)
    score = 0.0
    for t in query:
        f = tf.get(t, 0)
        if f == 0:
            continue
        score += idf(t) * f / (f + K)
    return score

print(round(bm25(["cheap", "flights"], {"cheap": 2, "flights": 3}, 60), 2))
